SELECT singer.Name, singer.Song_release_year FROM singer INNER JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID INNER JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID WHERE singer_in_concert.Singer_ID = (SELECT Singer_ID FROM singer ORDER BY singer.Song_release_year ASC LIMIT 1);
SELECT DISTINCT singer.Name, singer.release_year FROM singer JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID WHERE concert.Year = (SELECT MAX(Song_release_year) FROM concert)
