SELECT DISTINCT Country FROM singer WHERE Birthday = '2001'
SELECT singer.Country, COUNT(singer.Singer_ID) AS Number_of_Singers FROM singer JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID GROUP BY singer.Country
SELECT singer.Country, COUNT(singer.Country) AS count FROM singer INNER JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID INNER JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID GROUP BY singer.Country;
SELECT singer.Name AS Singer, singer_in_concert.Song_Name AS Song FROM singer INNER JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID WHERE singer_in_concert.concert.Year >= (SELECT AVG(Song_release_year) FROM concert GROUP BY concert.concert_ID)
SELECT singer.Song_Name FROM singer INNER JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID WHERE singer_in_concert.concert.Year > (SELECT AVG(Song_release_year) FROM concert)
SELECT stadium.Location, stadium.Name FROM stadium INNER JOIN singer_in_concert ON stadium.Stadium_ID = singer_in_concert.Stadium_ID WHERE singer_in_concert.Singer_ID IN (SELECT Singer_ID FROM singer_in_concert WHERE concert.Year = (SELECT Year FROM concert WHERE concert.Year BETWEEN 5000 AND 10000))
SELECT Location, Name FROM stadium INNER JOIN singer_in_concert ON stadium.Stadium_ID = singer_in_concert.Stadium_ID WHERE Capacity BETWEEN 5000 AND 10000;
SELECT AVG(Capacity), MAX(Capacity) FROM stadium;
