SELECT singer.Name, concert.Theme, singer_in_concert.Singer_ID AS number_of_singers FROM concert INNER JOIN singer_in_concert ON concert.concert_ID = singer_in_concert.concert_ID GROUP BY concert.Theme, singer_in_concert.Singer_ID;
