SELECT conductor.Name, orchestra.Orchestra FROM conductor INNER JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID GROUP BY conductor.Name ORDER BY orchestra.Orchestra_ID DESC LIMIT 1;
SELECT conductor.Name, orchestra.Orchestra FROM conductor INNER JOIN orchestra ON orchestra.Conductor_ID = conductor.Conductor_ID ORDER BY conductor.Year_of_Work DESC;
SELECT conductor.Name FROM conductor JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID JOIN performance ON orchestra.Orchestra_ID = performance.Orchestra_ID JOIN show ON performance.Show_ID = show.Show_ID WHERE show.If_first_show = '1' AND show.Performance_ID = performance.Performance_ID ORDER BY performance.Weekly_rank DESC;
SELECT conductor.Name FROM conductor JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID JOIN performance ON orchestra.Orchestra_ID = performance.Orchestra_ID JOIN show ON performance.Performance_ID = show.Performance_ID WHERE show.If_first_show = 'Yes' AND show.Record_Company = 'latest_orchestras' ORDER BY conductor.Name
SELECT orchestra.Record_Company, COUNT(orchestra.Orchestra_ID) AS number_of_orchestras FROM orchestra JOIN conductor ON orchestra.Conductor_ID = conductor.Conductor_ID GROUP BY orchestra.Record_Company
SELECT COUNT(DISTINCT orchestra.Orchestra_ID) AS total_orchestras FROM orchestra;
SELECT orchestra.Major_Record_Format FROM orchestra ORDER BY orchestra.Year_of_Founded ASC;
SELECT o.Major_Record_Format, o.Year_of_Founded FROM orchestra o JOIN performance p ON o.Orchestra_ID = p.Orchestra_ID JOIN show s ON p.Show_ID = s.Show_ID ORDER BY o.Year_of_Founded ASC;
SELECT orchestra.Orchestra, conductor.Conductor_ID, conductor.Name, conductor.Nationality, conductor.birthday, conductor.Year_of_Work, performance.Performance_ID, performance.Type, performance.Date, performance.Official_ratings_(millions), performance.Weekly_rank, show.Show_ID, show.Result, show.Attendance FROM conductor JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID JOIN performance ON performance.Orchestra_ID = orchestra.Orchestra_ID JOIN show ON show.Performance_ID = performance.Performance_ID WHERE orchestra.Year_of_Founded IS NOT NULL AND performance.Weekly_rank IS NOT NULL AND show.Result IS NOT NULL ORDER BY conductor.birthday ASC;
SELECT orchestra.Record_Company FROM orchestra JOIN performance ON orchestra.Orchestra = performance.Orchestra_ID JOIN conductor ON orchestra.Conductor_ID = conductor.Conductor_ID JOIN show ON performance.Performance_ID = show.Performance_ID WHERE show.If_first_show = '1' ORDER BY orchestra.Year_of_Founded DESC;
SELECT orchestra.Orchestra FROM orchestra JOIN conductor ON orchestra.Conductor_ID = conductor.Conductor_ID WHERE conductor.Nationality IS NULL;
SELECT orchestra.Orchestra FROM orchestra INNER JOIN conductor ON orchestra.Conductor_ID = conductor.Conductor_ID WHERE conductor.Nationality IS NULL;
SELECT orchestra.Record_Company FROM orchestra JOIN conductor ON orchestra.Conductor_ID = conductor.Conductor_ID WHERE orchestra.Year_of_Founded <= 2003;
SELECT DISTINCT Record_Company FROM orchestra JOIN conductor ON orchestra.Conductor_ID = conductor.Conductor_ID WHERE orchestra.Year_of_Founded > 2003 AND conductor.Nationality IS NULL;
SELECT COUNT(*) AS number_of_first_shows FROM show WHERE show.If_first_show = TRUE;
SELECT COUNT(*) FROM show WHERE If_first_show = '1'
