SELECT Professionals.professional_id, Professionals.last_name, Professionals.cell_number FROM Professionals JOIN Owners ON Owners.owner_id = Professionals.owner_id JOIN Dogs ON Dogs.owner_id = Owners.owner_id JOIN Sizes ON Dogs.size_code = Sizes.size_code JOIN Breeds ON Dogs.breed_code = Breeds.breed_code JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code JOIN Treatments ON Treatments.dog_id = Dogs.dog_id WHERE Professionals.state = 'Indiana' OR Treatments.date_of_treatment > 2;
SELECT Dogs.name FROM Dogs WHERE Dogs.date_departed IS NULL OR Dogs.date_departed < (SELECT MIN(date_of_departed) FROM Treatments WHERE cost_of_treatment <= 1000)
SELECT Dogs.name FROM Dogs INNER JOIN Treatments ON Dogs.dog_id = Treatments.dog_id INNER JOIN Professionals ON Treatments.professional_id = Professionals.professional_id INNER JOIN Owners ON Professionals.owner_id = Owners.owner_id WHERE Treatments.cost_of_treatment > 1000;
SELECT DISTINCT o.first_name FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id JOIN Professionals p ON d.professional_id = p.professional_id JOIN Treatment_Types t ON p.professional_id = t.professional_id WHERE d.abandoned_yn = 'N' AND d.breed_code IS NOT NULL AND d.size_code IS NOT NULL AND d.name IS NOT NULL AND p.first_name IS NOT NULL AND p.last_name IS NOT NULL
SELECT DISTINCT o.first_name FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id JOIN Professionals p ON d.dog_id = p.professional_id JOIN Treatment_Types t ON p.professional_id = t.treatment_type_code WHERE d.abandoned_yn = 'N' AND p.role_code = 'PROFESSIONAL' AND p.role_code = 'OWNER' AND t.treatment_type_code = NULL;
SELECT p.professional_id, p.first_name, p.last_name, p.email_address, p.home_phone, p.cell_number FROM Professionals p JOIN Dogs d ON d.owner_id = p.owner_id WHERE d.abandoned_yn = 'N' AND d.date_departed IS NULL;
SELECT Dogs.id, Dogs.name FROM Dogs INNER JOIN Treatments ON Dogs.dog_id = Treatments.dog_id INNER JOIN Professionals ON Treatments.professional_id = Professionals.professional_id WHERE Professionals.role_code = 'Professional' AND Dogs.abandoned_yn = 'N' AND Dogs.breed_code = NULL;
