SELECT Owners.owner_id, Owners.first_name, Owners.last_name, Owners.street, Owners.city, Owners.state, Owners.zip_code, Owners.email_address, Owners.home_phone, Owners.cell_number, Dogs.owner_id, Dogs.name, Dogs.breed_code, Dogs.size_code, Dogs.name, Dogs.age, Dogs.date_of_birth, Dogs.gender, Dogs.weight, Dogs.date_arrived, Dogs.date_adopted, Dogs.date_departed FROM Owners LEFT JOIN Dogs ON Dogs.owner_id = Owners.owner_id WHERE Dogs.dog_id IS NULL OR Dogs.owner_id IS NULL OR Dogs.breed_code IS NULL OR Dogs.size_code IS NULL OR Dogs.name IS NULL OR Dogs.age IS NULL OR Dogs.date_of_birth IS NULL OR Dogs.gender IS NULL OR Dogs.weight IS NULL OR Dogs.date_arrived IS NULL OR Dogs.date_departed IS NULL OR Dogs.date_of_birth IS NULL OR Dogs.gender IS NULL OR Dogs.weight IS NULL OR Dogs.date_arrived IS NULL OR Dogs.date_departed IS NULL ORDER BY Owners.owner_id ASC;
SELECT p.professional_id, o.street, o.cell_number, o.email_address, o.home_phone FROM Owners o JOIN Professionals p ON o.owner_id = p.owner_id JOIN Dogs d ON o.owner_id = d.owner_id JOIN Treatment_Types t ON d.dog_id = t.dog_id JOIN Charges c ON d.dog_id = c.charge_id JOIN Sizes s ON d.size_code = s.size_code JOIN Breeds b ON d.breed_code = b.breed_code WHERE p.role_code = 'Professional' AND d.abandoned_yn = 'N' AND t.treatment_type_code = 'Treatments' AND p.professional_id IS NOT NULL;
SELECT p.professional_id, d.name, t.home_phone, t.cell_number FROM Professionals p JOIN Dogs d ON p.owner_id = d.owner_id JOIN Treatments t ON d.dog_id = t.dog_id WHERE t.treatment_type_code = (SELECT treatment_type_code FROM Treatment_Types WHERE treatment_type_description = 'Two or More Treatments')
SELECT breed_name FROM Breeds ORDER BY breed_code ASC LIMIT 1;
SELECT breed_name FROM Breeds WHERE breed_code IN (SELECT Dogs.breed_code FROM Dogs JOIN Treatments ON Dogs.dog_id = Treatments.dog_id JOIN Professionals ON Treatments.professional_id = Professionals.professional_id JOIN Owners ON Dogs.owner_id = Owners.owner_id GROUP BY Dogs.breed_code HAVING COUNT(DISTINCT Dogs.owner_id) = 1)
SELECT o.owner_id, o.last_name, t.cost_of_treatment AS total_cost FROM Owners o INNER JOIN Treatments t ON o.owner_id = t.dog_id ORDER BY total_cost DESC LIMIT 1;
SELECT Dogs.owner_id, Owners.last_name FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id ORDER BY Dogs.date_departed DESC LIMIT 1;
SELECT treatment_type_description FROM Treatment_Types ORDER BY cost_of_treatment ASC LIMIT 1;
SELECT treatment_type_description, cost_of_treatment FROM Treatments INNER JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code WHERE cost_of_treatment < (SELECT cost_of_treatment FROM Treatments ORDER BY cost_of_treatment LIMIT 1) GROUP BY treatment_type_description
SELECT o.owner_id, o.zip_code, o.first_name, o.last_name, o.street, o.city, o.state, o.zip_code, o.email_address, o.home_phone, o.cell_number FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id JOIN Treatments t ON d.dog_id = t.dog_id GROUP BY o.owner_id, o.zip_code ORDER BY t.cost_of_treatment DESC LIMIT 1;
SELECT Dogs.owner_id, Dogs.zip_code FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id INNER JOIN Treatments ON Dogs.dog_id = Treatments.dog_id INNER JOIN Professionals ON Treatments.professional_id = Professionals.professional_id INNER JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code GROUP BY Dogs.owner_id, Dogs.zip_code ORDER BY Charges.charge_amount DESC LIMIT 1;
SELECT p.professional_id, p.first_name, p.last_name, p.email_address, p.home_phone, p.cell_number, t.treatment_type_description, t.date_of_treatment, t.cost_of_treatment FROM Professionals p JOIN Treatments t ON p.professional_id = t.professional_id JOIN Treatment_Types t2 ON t.treatment_type_code = t2.treatment_type_code WHERE t.treatment_type_code IN (1, 2, 3) ORDER BY p.professional_id;
SELECT p.professional_id, d.dog_id, t.treatment_type_code, t.date_of_treatment, t.cost_of_treatment, t.treatment_type_description FROM Professionals p JOIN Treatments t ON p.professional_id = t.professional_id JOIN Dogs d ON t.dog_id = d.dog_id WHERE t.treatment_type_code IN (SELECT treatment_type_code FROM Treatment_Types WHERE treatment_type_description = 'Treatments') AND t.cost_of_treatment > 0;
SELECT p.first_name, p.last_name, p.email_address, p.home_phone, p.cell_number FROM Professionals p JOIN Treatments t ON p.professional_id = t.professional_id JOIN Dogs d ON t.dog_id = d.dog_id WHERE t.cost_of_treatment < (SELECT AVG(cost_of_treatment) FROM Charges c WHERE c.charge_type = 'treatment')
SELECT o.first_name, o.last_name, o.street, o.city, o.state, o.zip_code, o.email_address, o.home_phone, o.cell_number FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id JOIN Treatments t ON d.dog_id = t.dog_id JOIN Professionals p ON p.professional_id = t.professional_id WHERE t.cost_of_treatment < (SELECT AVG(cost_of_treatment) FROM Charges) GROUP BY o.first_name, o.last_name, o.street, o.city, o.state, o.zip_code, o.email_address, o.home_phone, o.cell_number;
SELECT Dogs.date_of_birth, Professionals.first_name, Professionals.last_name FROM Dogs JOIN Professionals ON Dogs.owner_id = Professionals.owner_id WHERE Dogs.date_of_birth IS NOT NULL;
SELECT Dogs.name, Professionals.first_name, Professionals.last_name FROM Dogs JOIN Professionals ON Dogs.owner_id = Professionals.owner_id JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code JOIN Dogs ON Treatments.dog_id = Dogs.dog_id JOIN Professionals ON Treatments.professional_id = Professionals.professional_id;
SELECT Dogs.name, Treatment_Types.treatment_type_description, Charges.charge_amount AS cost_of_treatment FROM Dogs INNER JOIN Treatment_Types ON Dogs.breed_code = Treatment_Types.treatment_type_code INNER JOIN Charges ON Charges.charge_id = Treatments.treatment_id;
SELECT Dogs.name, Treatment_Types.treatment_type_description, Charges.charge_amount FROM Dogs JOIN Charges ON Dogs.dog_id = Charges.charge_id JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code;
SELECT Owners.first_name, Dogs.size_code, Dogs.size_description FROM Owners INNER JOIN Dogs ON Dogs.owner_id = Owners.owner_id;
SELECT Dogs.name, Dogs.weight FROM Dogs JOIN Owners ON Dogs.owner_id = Owners.owner_id;
SELECT Dogs.name, Owners.first_name, Owners.last_name, Dogs.name AS dog_name FROM Dogs JOIN Owners ON Dogs.owner_id = Owners.owner_id;
SELECT Dogs.name, Owners.first_name, Owners.last_name, Dogs.owner_id, Dogs.breed_code, Dogs.size_code, Dogs.name, Dogs.dog_id, Dogs.abandoned_yn, Dogs.breed_name, Dogs.size_description, Dogs.name, Dogs.date_of_birth, Dogs.gender, Dogs.weight, Dogs.date_arrived, Dogs.date_departed, Treatments.treatment_type_description, Treatments.date_of_treatment, Treatments.cost_of_treatment FROM Dogs JOIN Owners ON Dogs.owner_id = Owners.owner_id JOIN Treatments ON Dogs.dog_id = Treatments.dog_id WHERE Dogs.abandoned_yn = 'N' AND Treatments.cost_of_treatment = '0' AND Treatments.treatment_type_code = '1'
SELECT Dogs.name, Treatments.date_of_treatment FROM Dogs JOIN Treatments ON Dogs.dog_id = Treatments.dog_id JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code JOIN Professionals ON Treatments.professional_id = Professionals.professional_id WHERE Treatments.treatment_type_code = 'rare' AND Treatments.cost_of_treatment IS NULL;
SELECT Dogs.name, Treatments.date_of_treatment FROM Dogs INNER JOIN Treatments ON Dogs.dog_id = Treatments.dog_id;
SELECT Dogs.owner_id, Dogs.name FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id WHERE Owners.state = 'VA' ORDER BY Owners.first_name;
SELECT Dogs.name, Owners.first_name FROM Dogs JOIN Owners ON Dogs.owner_id = Owners.owner_id WHERE Owners.state = 'VA' AND Dogs.abandoned_yn = 'N' ORDER BY Dogs.name ASC;
SELECT d.date_departed, t.date_of_treatment FROM Dogs d JOIN Treatments t ON d.dog_id = t.dog_id;
SELECT Dogs.date_departed, Dogs.date_arrived FROM Dogs JOIN Treatments ON Dogs.date_departed = Treatments.date_of_treatment JOIN Professionals ON Treatments.professional_id = Professionals.professional_id JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code;
SELECT Dogs.owner_id, Owners.last_name FROM Dogs JOIN Owners ON Dogs.owner_id = Owners.owner_id WHERE Dogs.age = (SELECT MIN(age) FROM Dogs)
SELECT o.last_name, d.name, d.age FROM Dogs d JOIN Owners o ON d.owner_id = o.owner_id ORDER BY d.age DESC LIMIT 1;
SELECT o.email_address FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id JOIN Treatments t ON d.dog_id = t.dog_id JOIN Professionals p ON p.professional_id = t.professional_id WHERE o.state = 'HI' OR o.state = 'WI' AND p.state = 'HI' OR p.state = 'WI';
SELECT email_address FROM Professionals INNER JOIN Owners ON Professionals.owner_id = Owners.owner_id WHERE state IN ('HI', 'WI') GROUP BY email_address
SELECT Dogs.date_departed, Dogs.date_arrived FROM Dogs JOIN Treatments ON Dogs.dog_id = Treatments.dog_id JOIN Professionals ON Treatments.professional_id = Professionals.professional_id JOIN Treatments ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code WHERE Dogs.abandoned_yn = 'A' AND Treatments.treatment_type_code = 'TREATMENT_TYPE_ABANDONED';
SELECT Dogs.date_departed, Dogs.date_arrived, Dogs.breed_code, Dogs.size_code, Dogs.name, Dogs.date_of_birth, Dogs.gender, Dogs.weight, Dogs.date_of_birth, Dogs.date_of_birth FROM Dogs JOIN Treatments ON Dogs.dog_id = Treatments.dog_id JOIN Professionals ON Treatments.professional_id = Professionals.professional_id JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code WHERE Dogs.abandoned_yn = 'A';
SELECT COUNT(*) FROM Dogs;
SELECT COUNT(DISTINCT Dogs.dog_id) FROM Dogs;
SELECT COUNT(DISTINCT Professionals.professional_id) FROM Professionals INNER JOIN Treatments ON Treatments.professional_id = Professionals.professional_id;
SELECT COUNT(DISTINCT Professionals.professional_id) FROM Professionals INNER JOIN Dogs ON Professionals.owner_id = Dogs.owner_id;
SELECT o.first_name, o.last_name FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id JOIN Professionals p ON d.professional_id = p.professional_id WHERE d.city LIKE '%West%'
SELECT p.first_name, p.last_name FROM Professionals p JOIN Owners o ON p.street = o.street JOIN Dogs d ON o.owner_id = d.owner_id JOIN Sizes s ON d.size_code = s.size_code JOIN Breeds b ON d.breed_code = b.breed_code WHERE p.city = 'West' AND d.name IS NOT NULL;
SELECT Owners.first_name, Owners.last_name FROM Owners INNER JOIN Dogs ON Dogs.owner_id = Owners.owner_id WHERE Dogs.state LIKE '%North%';
