SELECT COUNT(DISTINCT Dogs.dog_id) FROM Dogs WHERE Dogs.abandoned_yn = 'Y' AND Dogs.age < (SELECT AVG(Dogs.age) FROM Dogs)
SELECT COUNT(DISTINCT Dogs.dog_id) FROM Dogs WHERE Dogs.abandoned_yn = 'A' AND Dogs.age < (SELECT AVG(Dogs.age) FROM Dogs)
SELECT cost_of_treatment FROM Treatments WHERE date_of_treatment = (SELECT MAX(date_of_treatment) FROM Treatments)
SELECT MAX(cost_of_treatment) FROM Treatments;
SELECT COUNT(DISTINCT Dogs.dog_id) FROM Dogs WHERE Dogs.abandoned_yn = 'Y' AND Dogs.date_departed IS NULL;
SELECT COUNT(*) AS number_of_dogs_that_have_received_any_treatment FROM Treatments JOIN Dogs ON Treatments.dog_id = Dogs.dog_id;
SELECT COUNT(DISTINCT Dogs.owner_id) FROM Dogs WHERE Dogs.abandoned_yn = 'N' AND Dogs.date_departed IS NULL;
SELECT COUNT(DISTINCT Owners.owner_id) FROM Owners JOIN Dogs ON Dogs.owner_id = Owners.owner_id WHERE Dogs.abandoned_yn = 'N' AND Dogs.breed_code IS NOT NULL;
SELECT COUNT(DISTINCT Professionals.professional_id) FROM Professionals INNER JOIN Treatments ON Treatments.professional_id = Professionals.professional_id INNER JOIN Dogs ON Dogs.dog_id = Treatments.dog_id WHERE Dogs.abandoned_yn = 'N' AND Dogs.gender = 'Male' AND Dogs.date_of_birth IS NULL;
SELECT COUNT(DISTINCT Professionals.professional_id) FROM Professionals INNER JOIN Treatments ON Treatments.professional_id = Professionals.professional_id;
SELECT Dogs.name, Dogs.age, Dogs.weight, Dogs.abandoned_yn FROM Dogs WHERE Dogs.abandoned_yn = '1' AND Dogs.abandoned_yn IS NOT NULL;
SELECT Dogs.name, Dogs.age, Dogs.weight, Dogs.abandoned_yn FROM Dogs JOIN Owners ON Dogs.owner_id = Owners.owner_id;
SELECT AVG(Dogs.age) FROM Dogs;
SELECT AVG(Dogs.age) FROM Dogs;
SELECT Dogs.age, Treatments.date_of_treatment, Treatment_Types.treatment_type_description FROM Dogs INNER JOIN Treatments ON Dogs.dog_id = Treatments.dog_id INNER JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code ORDER BY Dogs.age DESC LIMIT 1;
SELECT Dogs.age AS age FROM Dogs ORDER BY Dogs.age DESC LIMIT 1
SELECT charge_type, charge_amount FROM Charges;
SELECT charge_type, charge_amount FROM Charges;
SELECT MAX(charge_amount) AS most_expensive_charge_cost FROM Charges;
SELECT charge_amount FROM Charges ORDER BY charge_amount DESC LIMIT 1
SELECT Dogs.name, Professionals.first_name, Professionals.last_name, Professionals.email_address, Professionals.home_phone, Professionals.cell_number FROM Professionals JOIN Dogs ON Professionals.owner_id = Dogs.owner_id WHERE Professionals.email_address IS NOT NULL;
SELECT Dogs.name, Professionals.email_address, Professionals.last_name FROM Professionals INNER JOIN Dogs ON Professionals.professional_id = Dogs.owner_id;
SELECT Dogs.breed_code, Dogs.size_code, Dogs.breed_name, Dogs.size_description, Dogs.name, Dogs.gender, Dogs.age, Dogs.date_of_birth, Dogs.date_arrived, Dogs.date_departed, Treatments.cost_of_treatment, Treatments.treatment_type_description, Treatment_Types.treatment_type_code, Treatment_Types.treatment_type_description FROM Dogs JOIN Treatments ON Dogs.dog_id = Treatments.dog_id JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code JOIN Breeds ON Dogs.breed_code = Breeds.breed_code JOIN Sizes ON Dogs.size_code = Sizes.size_code;
SELECT DISTINCT breed_name, size_description FROM Dogs JOIN Sizes ON Dogs.size_code = Sizes.size_code;
SELECT Professionals.first_name, Professionals.last_name, Treatment_Types.treatment_type_description FROM Professionals JOIN Treatment_Types ON Professionals.professional_id = Treatments.professional_id JOIN Dogs ON Dogs.dog_id = Treatments.dog_id JOIN Owners ON Dogs.owner_id = Owners.owner_id JOIN Sizes ON Dogs.size_code = Sizes.size_code;
SELECT Professionals.first_name, Professionals.last_name, Treatments.date_of_treatment, Treatments.cost_of_treatment FROM Professionals INNER JOIN Treatments ON Professionals.professional_id = Treatments.professional_id;
SELECT COUNT(*) FROM singer;
SELECT COUNT(*) AS count_of_singers FROM singer;
SELECT Name FROM singer ORDER BY Birth_Year ASC;
SELECT Name FROM singer ORDER BY Birth_Year ASC;
SELECT singer.Birth_Year, singer.Citizenship FROM singer;
SELECT Singer_ID, Citizenship FROM singer ORDER BY Birth_Year;
SELECT Name FROM singer WHERE Citizenship != 'French'
SELECT Name FROM singer WHERE Citizenship != 'French'
SELECT Name FROM singer WHERE Birth_Year < 1948
SELECT Name FROM singer WHERE Birth_Year <= 1948
SELECT Name FROM singer WHERE Birth_Year = (SELECT MIN(Birth_Year) FROM singer)
SELECT Name FROM singer WHERE Birth_Year < (SELECT MIN(Birth_Year) FROM singer)
SELECT Citizenship, COUNT(*) AS Number_of_Singers FROM singer GROUP BY Citizenship
SELECT Citizenship, COUNT(Singer_ID) AS Total_Singers FROM singer GROUP BY Citizenship
SELECT Citizenship, COUNT(*) AS Most_Common_Citizenship FROM singer GROUP BY Citizenship ORDER BY COUNT(*) DESC;
SELECT DISTINCT Citizenship FROM singer;
SELECT DISTINCT Citizenship, MAX(Sales) AS Highest_Net_Worth FROM singer JOIN song ON song.Singer_ID = singer.Singer_ID GROUP BY Citizenship;
SELECT Citizenship, MAX(Net_Worth_Millions) AS Highest_Net_Worth FROM singer GROUP BY Citizenship
SELECT song.Title AS Song, singer.Name AS Singer, song.Highest_Position AS Position FROM song JOIN singer ON song.Singer_ID = singer.Singer_ID ORDER BY song.Highest_Position DESC;
SELECT DISTINCT Name, Highest_Position FROM song JOIN singer ON song.Singer_ID = singer.Singer_ID ORDER BY Highest_Position DESC;
SELECT DISTINCT s.Name FROM singer s JOIN song s2 ON s.Singer_ID = s2.Singer_ID WHERE s2.Sales > 300000;
SELECT DISTINCT Name FROM singer WHERE Net_Worth_Millions > 300000;
SELECT Name FROM singer WHERE Singer_ID IN (SELECT Singer_ID FROM song GROUP BY Singer_ID HAVING COUNT(Song_ID) > 1)
SELECT Name FROM singer WHERE Birth_Year IS NOT NULL AND Net_Worth_Millions IS NOT NULL AND Singer_ID IN (SELECT Singer_ID FROM song GROUP BY Singer_ID HAVING COUNT(Song_ID) > 1)
SELECT s.Name, s.Sales, s.Highest_Position FROM singer s JOIN song s ON s.Singer_ID = song.Singer_ID;
SELECT Name, MAX(Highest_Position) AS Max_Highest_Position FROM singer JOIN song ON song.Singer_ID = singer.Singer_ID GROUP BY Name;
SELECT Name FROM singer WHERE Singer_ID NOT IN (SELECT Singer_ID FROM song WHERE Sales IS NULL)
SELECT singer.Name AS sname FROM singer INNER JOIN song ON singer.Singer_ID = song.Singer_ID WHERE song.Sales IS NULL;
SELECT singer.Citizenship FROM singer INNER JOIN song ON singer.Singer_ID = song.Singer_ID WHERE song.Sales >= 0 AND singer.Birth_Year < 1945;
SELECT Citizenship FROM singer WHERE Birth_Year < 1945;
